"""Persistent reservation and exact allgather-plan compiler service."""
from __future__ import annotations

import re

from compiler import PlanFailure, compile_plan, find_deficient_cut

ID_RE = re.compile(r"[A-Za-z0-9_.-]{1,32}\Z", re.ASCII)
MAX_TICK = 10 ** 12


class Invalid(Exception):
    pass


def _bad():
    raise Invalid()


def _int(v, lo, hi):
    if type(v) is not int or v < lo or v > hi:
        _bad()
    return v


def _bool(v):
    if type(v) is not bool:
        _bad()
    return v


def _list(v, minlen=0, maxlen=None):
    if type(v) is not list:
        _bad()
    if len(v) < minlen or (maxlen is not None and len(v) > maxlen):
        _bad()
    return v


def _exact(obj, keys):
    if type(obj) is not dict or set(obj.keys()) != set(keys):
        _bad()
    return obj


def _ident(v):
    if type(v) is not str or ID_RE.fullmatch(v) is None:
        _bad()
    return v


def _window(v):
    a = _list(v, 2, 2)
    s = _int(a[0], 0, MAX_TICK)
    e = _int(a[1], 0, MAX_TICK)
    if s >= e:
        _bad()
    return (s, e)


def _envelope(v):
    a = _list(v, 0, 128)
    out = {}
    for item in a:
        p = _list(item, 2, 2)
        l = _int(p[0], 0, 127)
        r = _int(p[1], 1, MAX_TICK)
        if l in out:
            _bad()
        out[l] = r
    return out


def _participants(v):
    a = _list(v, 2, 32)
    out = {}
    total = 0
    for item in a:
        p = _list(item, 2, 2)
        node = _int(p[0], 0, 47)
        rate = _int(p[1], 0, MAX_TICK)
        if node in out:
            _bad()
        out[node] = rate
        total += rate
    if total <= 0:
        _bad()
    return out


def _overlap_ok(link_caps, bookings):
    """Check the initial committed bookings against base capacities."""
    m = len(link_caps)
    starts = sorted({b['window'][0] for b in bookings})
    for t in starts:
        used = [0] * m
        for b in bookings:
            s, e = b['window']
            if s <= t < e:
                for l, rate in b['env'].items():
                    used[l] += rate
        for l, cap in enumerate(link_caps):
            if used[l] > cap:
                _bad()
    return True


class Controller:
    def __init__(self):
        self.loaded = False
        self.rev = 0
        self.now = 0
        self.n = 0
        self.links = []          # [(u, v)]
        self.caps = []           # current base capacity by link id
        self.records = {}        # id -> history/state record

    # ---------------- small response helpers ----------------
    def _err(self, code, rev=None):
        return {'status': 'error', 'code': code,
                'rev': self.rev if rev is None else rev}

    def _stale(self):
        return {'status': 'stale', 'rev': self.rev}

    def _not_loaded(self):
        return {'status': 'error', 'code': 'NOT_LOADED', 'rev': 0}

    def _live_records(self):
        return [(i, r) for i, r in self.records.items() if r['state'] == 'live']

    def _used_at(self, link, tick):
        total = 0
        for _, r in self._live_records():
            s, e = r['window']
            if s <= tick < e:
                total += r['env'].get(link, 0)
        return total

    def _used_vector(self, tick):
        used = [0] * len(self.links)
        for _, r in self._live_records():
            s, e = r['window']
            if s <= tick < e:
                for l, rate in r['env'].items():
                    used[l] += rate
        return used

    # ---------------- load parsing ----------------
    def _parse_load(self, req):
        _exact(req, ('op', 'n', 'links', 'bookings'))
        n = _int(req['n'], 2, 48)
        raw_links = _list(req['links'], 0, 128)
        links = []
        link_caps = []
        seen = set()
        for item in raw_links:
            p = _list(item, 3, 3)
            u = _int(p[0], 0, 47)
            v = _int(p[1], 0, 47)
            cap = _int(p[2], 0, MAX_TICK)
            if u == v or u >= n or v >= n:
                _bad()
            key = (u, v) if u < v else (v, u)
            if key in seen:
                _bad()
            seen.add(key)
            links.append((u, v))
            link_caps.append(cap)

        raw_bookings = _list(req['bookings'], 0, 128)
        bookings = []
        ids = set()
        total_entries = 0
        for item in raw_bookings:
            b = _exact(item, ('id', 'owner', 'window', 'envelope'))
            bid = _ident(b['id'])
            owner = _ident(b['owner'])
            win = _window(b['window'])
            env = _envelope(b['envelope'])
            if bid in ids:
                _bad()
            ids.add(bid)
            for l in env:
                if l >= len(links):
                    _bad()
            total_entries += len(env)
            if total_entries > 2048:
                _bad()
            bookings.append({'id': bid, 'owner': owner, 'window': win,
                             'env': env})
        return n, links, link_caps, bookings

    # ---------------- preparation parsing ----------------
    def _parse_prepare(self, req):
        _exact(req, ('op', 'id', 'owner', 'window', 'period',
                     'participants', 'envelope', 'rev'))
        ident = _ident(req['id'])
        owner = _ident(req['owner'])
        win = _window(req['window'])
        period = _int(req['period'], 1, 10 ** 6)
        parts = _participants(req['participants'])
        env = _envelope(req['envelope'])
        rev = _int(req['rev'], 0, MAX_TICK)
        key = (owner, win[0], win[1], period, rev,
               tuple(sorted(parts.items())), tuple(sorted(env.items())))
        return ident, owner, win, period, parts, env, rev, key

    # ---------------- operation implementations ----------------
    def _load(self, req):
        n, links, caps, bookings = self._parse_load(req)
        if self.loaded:
            return self._err('ALREADY_LOADED')
        _overlap_ok(caps, bookings)

        self.loaded = True
        self.rev = 0
        self.now = 0
        self.n = n
        self.links = links
        self.caps = list(caps)
        self.records = {}
        for b in bookings:
            self.records[b['id']] = {
                'origin': 'load',
                'owner': b['owner'],
                'window': b['window'],
                'env': dict(b['env']),
                'state': 'live',
            }
        return {'status': 'ok', 'rev': 0, 'now': 0}

    def _audit(self, req):
        _exact(req, ('op', 'at'))
        raw = _list(req['at'], 0, 8)
        ticks = [_int(t, 0, MAX_TICK) for t in raw]
        if not self.loaded:
            return self._not_loaded()
        if any(t < self.now for t in ticks):
            return self._err('TIME')
        live = sorted(i for i, r in self.records.items() if r['state'] == 'live')
        samples = []
        for t in ticks:
            used = self._used_vector(t)
            samples.append([t, [self.caps[l] - used[l] for l in range(len(self.links))]])
        return {'status': 'ok', 'rev': self.rev, 'now': self.now,
                'leases': live, 'samples': samples}

    def _advance(self, req):
        _exact(req, ('op', 'time'))
        t = _int(req['time'], 0, MAX_TICK)
        if not self.loaded:
            return self._not_loaded()
        if t < self.now:
            return self._err('TIME')
        expired = []
        for ident, r in self.records.items():
            if r['state'] == 'live' and r['window'][1] <= t:
                r['state'] = 'expired'
                expired.append(ident)
        expired.sort()
        self.now = t
        self.rev += 1
        return {'status': 'ok', 'rev': self.rev, 'now': t,
                'expired': expired}

    def _parse_changes(self, req):
        _exact(req, ('op', 'rev', 'changes', 'force'))
        rev = _int(req['rev'], 0, MAX_TICK)
        force = _bool(req['force'])
        raw = _list(req['changes'], 0, 128)
        changes = []
        seen = set()
        for item in raw:
            p = _list(item, 2, 2)
            l = _int(p[0], 0, 127)
            c = _int(p[1], 0, MAX_TICK)
            if l in seen:
                _bad()
            seen.add(l)
            changes.append((l, c))
        return rev, force, changes

    def _edit_block_witness(self, changes):
        newcap = dict(changes)
        changed_links = sorted(newcap)
        candidates = {self.now}
        for _, r in self._live_records():
            s, e = r['window']
            if s >= self.now:
                candidates.add(s)
        # Only starts can raise used(l,t); ends lower it.
        for t in sorted(candidates):
            used = {l: 0 for l in changed_links}
            for _, r in self._live_records():
                s, e = r['window']
                if s <= t < e:
                    for l, rate in r['env'].items():
                        if l in used:
                            used[l] += rate
            for l in changed_links:
                c = newcap[l]
                if used[l] > c:
                    return l, t, used[l], c
        return None

    def _edit(self, req):
        rev, force, changes = self._parse_changes(req)
        if not self.loaded:
            return self._not_loaded()
        if rev != self.rev:
            return self._stale()
        for l, _ in changes:
            if l >= len(self.links):
                return self._err('REFERENCE')
        if force:
            decreases = {l for l, c in changes if c < self.caps[l]}
            cancelled = []
            if decreases:
                for ident, r in self.records.items():
                    if r['state'] == 'live' and any(l in r['env'] for l in decreases):
                        r['state'] = 'revoked'
                        cancelled.append(ident)
            for l, c in changes:
                self.caps[l] = c
            cancelled.sort()
            self.rev += 1
            return {'status': 'ok', 'rev': self.rev, 'cancelled': cancelled}

        witness = self._edit_block_witness(changes)
        if witness is not None:
            l, t, u, c = witness
            return {'status': 'blocked', 'rev': self.rev, 'link': l,
                    'time': t, 'used': u, 'capacity': c}
        for l, c in changes:
            self.caps[l] = c
        self.rev += 1
        return {'status': 'ok', 'rev': self.rev, 'cancelled': []}

    def _capacity_denial(self, s, e, env):
        candidates = {s}
        for _, r in self._live_records():
            s0 = r['window'][0]
            if s <= s0 < e:
                candidates.add(s0)
        for l in sorted(env):
            b = env[l]
            for t in sorted(candidates):
                if not (s <= t < e):
                    continue
                u = self._used_at(l, t) + b
                if u > self.caps[l]:
                    return l, t, u, self.caps[l]
        return None

    def _record_denied(self, ident, owner, win, env, key):
        self.records[ident] = {
            'origin': 'prepare',
            'owner': owner,
            'window': win,
            'env': dict(env),
            'state': 'denied',
            'payload_key': key,
            'base_rev': self.rev,
            'prepare_outcome': 'denied',
        }

    def _prepare(self, req):
        ident, owner, win, period, parts, env, rev, key = self._parse_prepare(req)
        if not self.loaded:
            return self._not_loaded()

        existing = self.records.get(ident)
        if existing is not None:
            if (existing.get('origin') == 'prepare' and
                    existing.get('payload_key') == key):
                return {'status': 'replay', 'id': ident, 'rev': self.rev,
                        'base_rev': existing['base_rev'],
                        'outcome': existing['prepare_outcome']}
            return self._err('CONFLICT')

        if rev != self.rev:
            return self._stale()
        # References were schema-bounded; now check them against the graph.
        for v in parts:
            if v >= self.n:
                return self._err('REFERENCE')
        for l in env:
            if l >= len(self.links):
                return self._err('REFERENCE')
        s, e = win
        if s < self.now:
            return self._err('TIME')
        if (e - s) % period != 0:
            return self._err('WINDOW')

        witness = self._capacity_denial(s, e, env)
        if witness is not None:
            l, t, u, c = witness
            self._record_denied(ident, owner, win, env, key)
            return {'status': 'denied', 'id': ident, 'rev': self.rev,
                    'kind': 'capacity', 'link': l, 'time': t,
                    'used': u, 'capacity': c}

        roots = dict(parts)
        try:
            outcome, payload = compile_plan(self.n, self.links, sorted(parts),
                                            roots, period, env)
        except PlanFailure:
            # This should only be reachable through an implementation fault on
            # a theoretically feasible instance.  Re-check for a cut so a valid
            # negative certificate is still emitted where possible.
            cut = find_deficient_cut(self.n, self.links, sorted(parts),
                                     roots, period, env)
            if cut is not None:
                self._record_denied(ident, owner, win, env, key)
                return {'status': 'denied', 'id': ident, 'rev': self.rev,
                        'kind': 'cut', 'cut': cut}
            raise

        if outcome == 'denied':
            self._record_denied(ident, owner, win, env, key)
            return {'status': 'denied', 'id': ident, 'rev': self.rev,
                    'kind': 'cut', 'cut': payload}

        self.records[ident] = {
            'origin': 'prepare',
            'owner': owner,
            'window': win,
            'env': dict(env),
            'state': 'prepared',
            'payload_key': key,
            'base_rev': self.rev,
            'prepare_outcome': 'prepared',
        }
        return {'status': 'prepared', 'id': ident, 'rev': self.rev,
                'plan': payload}

    def _commit(self, req):
        _exact(req, ('op', 'id', 'owner', 'rev'))
        ident = _ident(req['id'])
        owner = _ident(req['owner'])
        rev = _int(req['rev'], 0, MAX_TICK)
        if not self.loaded:
            return self._not_loaded()
        rec = self.records.get(ident)
        if rec is None:
            return self._err('MISSING')
        if rec['owner'] != owner:
            return self._err('OWNER')
        state = rec['state']
        if state == 'live':
            return {'status': 'ok', 'id': ident, 'rev': self.rev,
                    'replay': True}
        if state in ('expired', 'cancelled', 'revoked'):
            return self._err('GONE')
        if state == 'denied':
            return self._err('DENIED')
        if state == 'prepared':
            if rev != self.rev or rec.get('base_rev') != self.rev:
                return self._stale()
            self.rev += 1
            if rec['window'][1] > self.now:
                rec['state'] = 'live'
            else:
                rec['state'] = 'expired'
            return {'status': 'ok', 'id': ident, 'rev': self.rev,
                    'replay': False}
        return self._err('MISSING')

    def _cancel(self, req):
        _exact(req, ('op', 'id', 'owner', 'rev'))
        ident = _ident(req['id'])
        owner = _ident(req['owner'])
        rev = _int(req['rev'], 0, MAX_TICK)
        if not self.loaded:
            return self._not_loaded()
        if rev != self.rev:
            return self._stale()
        rec = self.records.get(ident)
        if rec is None or rec['state'] != 'live':
            return self._err('MISSING')
        if rec['owner'] != owner:
            return self._err('OWNER')
        rec['state'] = 'cancelled'
        self.rev += 1
        return {'status': 'ok', 'rev': self.rev, 'released': ident}

    # ---------------- dispatch ----------------
    def handle(self, req):
        try:
            if type(req) is not dict:
                _bad()
            op = req.get('op')
            if type(op) is not str:
                _bad()
            if op == 'about':
                _exact(req, ('op',))
                return {'status': 'ok', 'protocol': 'forest-controller/3'}
            if op == 'load':
                return self._load(req)
            if op == 'audit':
                return self._audit(req)
            if op == 'advance':
                return self._advance(req)
            if op == 'edit':
                return self._edit(req)
            if op == 'prepare':
                return self._prepare(req)
            if op == 'commit':
                return self._commit(req)
            if op == 'cancel':
                return self._cancel(req)
            _bad()
        except Invalid:
            return {'status': 'invalid'}


_controller = Controller()


def handle(request):
    return _controller.handle(request)
